const express = require('express');
const axios = require('axios');
const app = express();
const cache = new Map();
const SERVICE_KEY = process.env.DATA_GO_KR_KEY;

app.get('/api/bus-stops', async (req, res) => {
  const city = req.query.cityCode;
  const url = `https://apis.data.go.kr/1613000/BusSttnInfoInqireService/getSttnNoList?serviceKey=${SERVICE_KEY}&cityCode=${encodeURIComponent(city)}&_type=json`;
