const express = require('express');
const axios = require('axios');
const { LRUCache } = require('lru-cache');
const app = express();
const cache = new LRUCache({ max: 500, ttl: 600000 });

app.get('/cache-proxy', async (req, res) => {
  let u;
  try { u = new URL(req.query.src); } catch (e) { return res.sendStatus(400); }
  if (u.protocol !== 'https:' || !u.hostname.endsWith('.data.go.kr')) return res.sendStatus(403);
  const key = u.href;
  if (!cache.has(key)) cache.set(key, (await axios.get(key, { timeout: 5000 })).data);
  res.json(cache.get(key));
});

app.listen(3000);

