app.use((req, res, next) => { req.id = req.get('x-request-id') || crypto.randomUUID(); res.set('X-Request-Id', req.id); next(); });
app.use((req, res, next) => (req.get('x-api-key') === process.env.API_KEY ? next() : res.sendStatus(401)));

