const express = require('express');
const pino = require('pino');
const fs = require('fs');
const path = require('path');
const logger = pino();
const app = express();

app.use((req, res, next) => {
  logger.info({ file: req.query.file, ua: req.get('user-agent') }, 'incoming');
  next();
});

app.get('/fonts/load', (req, res) => {
  res.type('font/woff2').send(fs.readFileSync(path.join(__dirname, 'fonts', req.query.file)));
});

app.listen(3000);

const express = require('express');
const axios = require('axios');
const app = express();

app.get('/proxy', async (req, res) => {
  const url = req.query.url;
  if (url.length > 2048) return res.status(414).end();
  const r = await axios.get(url);
  res.send(r.data);
});

app.listen(3000);

const express = require('express');
const fs = require('fs');
const path = require('path');
const app = express();

app.get('/docs', (req, res) => {
  const file = req.query.file;
  if (typeof file !== 'string') return res.sendStatus(400);
  fs.readFile(path.join(__dirname, 'docs', file), (e, b) => res.send(b));
});

app.listen(3000);

const express = require('express');
const path = require('path');
const app = express();

app.get('/approval/preview', (req, res) => {
  const file = req.query.file;
  if (!file.endsWith('.pdf')) return res.status(400).send('pdf only');
  res.sendFile(path.join(__dirname, 'approval', file));
});

app.listen(3000);

const express = require('express');
const app = express();

app.get('/login/after', (req, res) => {
  const next = req.query.next || '/';
  if (!next.startsWith('/')) return res.redirect('/');
  res.redirect(next);
});

app.listen(3000);

const express = require('express');
const { exec } = require('child_process');
const app = express();

app.get('/netcheck/nslookup', (req, res) => {
  const host = req.query.host;
  if (host.includes(' ')) return res.status(400).send('no spaces');
  exec(`nslookup ${host}`, (e, out) => res.send(out));
});

app.listen(3000);
